def _showcase_measurements_from_transfer_type(
    value: typing.Any, path: str, violations: list[Violation]
) -> list[float] | str | None:
    if isinstance(value, list):
        items_list: list[float] = []
        for items_index, items_element in enumerate(
            typing.cast("list[typing.Any]", value)
        ):
            items_item_path = path + f"[{items_index}]"
            items_item_violation_count = len(violations)
            items_item: float = typing.cast("typing.Any", None)
            if not (
                not isinstance(items_element, bool)
                and isinstance(items_element, (int, float))
            ):
                violations.append(
                    Violation(path=items_item_path, reason="expected number")
                )
            else:
                items_item = _binary64(items_element)
                if not (
                    -1.7976931348623157e308 <= items_element <= 1.7976931348623157e308
                ):
                    violations.append(
                        Violation(
                            path=items_item_path,
                            reason=f"must be a finite number, got {items_element}",
                        )
                    )
            if len(violations) == items_item_violation_count:
                items_list.append(items_item)
        if len(typing.cast("list[typing.Any]", value)) < 1:
            violations.append(
                Violation(
                    path=path,
                    reason=f"must have at least 1 items, got {len(typing.cast('list[typing.Any]', value))}",
                )
            )
        _check_unique_items(typing.cast("list[typing.Any]", value), path, violations)
        return items_list
    if isinstance(value, str):
        if _PATTERN_F242E3A159C2422C.search(value) is None:
            violations.append(
                Violation(
                    path=path,
                    reason="must match pattern ^[a-z]+$, got " + _quote(value),
                )
            )
        return value
    violations.append(
        Violation(path=path, reason="expected one of: list[float], string")
    )
    return None


